int VDI_GetHdr ( struct busyobj * bo ) { const struct director * d ; struct vrt_ctx ctx [ 1 ] ; int i = - 1 ; CHECK_OBJ_NOTNULL ( bo , BUSYOBJ_MAGIC ) ; VCL_Bo2Ctx ( ctx , bo ) ; d = VDI_Resolve ( ctx ) ; if ( d != NULL ) { VRT_Assign_Backend ( & bo -> director_resp , d ) ; AN ( d -> vdir -> methods -> gethdrs ) ; bo -> director_state = DIR_S_HDRS ; i = d -> vdir -> methods -> gethdrs ( ctx , d ) ; } if ( i ) { bo -> director_state = DIR_S_NULL ; } return ( i ) ; } 